function openDetail(userid, formid, status, form_type, institution_id, id) {
    //localStorage.setItem("etrackById", id);
    localStorage.setItem("userid", userid);
    localStorage.setItem("formid", formid);
    sessionStorage.setItem("status", status);
    var usertype = localStorage.getItem("typeuser");

    var app =
        getParameterByName("App")?.toUpperCase() ||
        getParameterByName("app")?.toUpperCase();

    const GetFormTypeEndpont = (formType) => {
        switch (formType) {
            // Permit
            case "WP_32":
                if ((status == "NCOS" || status == "NCOC") && user_type == "2") {
                    return "/Permit/TrackingEdit";
                }
                return "/Permit/DetailTracking";
            case "MT_13_EXIT":
                return "/Forms/DetailFormRequestExit13";
            case "MT_13_1_INFORM":
                return "/Permit/DetailTracking13Begin";
            case "MT_41_4_59":
                return "/RequestForm41/DetailRequest41";
            case "MT_43":
                return "/Forms/DetailFormRequest43";
            case "MT_46_59":
                return "/RequestForm46_59/DetailFormRequest46_59";
            case "MT_50_1":
                return "/Forms/DetailFormRequest50";
            case "MT_59":
                return "/RequestForm59/DetailTracking59";
            case "MT_60_1":
                return "/Permit/DetailTracking60_1";
            case "MT_60_2":
                return "/Permit/DetailTracking60_2";
            case "MT_61":
                return "/Permit/DetailTracking61";
            case "MT_62_BOI":
                return "/RequestFormBOI62/DetailFormRequestBOI62";
            case "MT_62":
                return "/RequestForm62/DetailFormRequest62";
            case "MT_63":
                return "/RequestForm63/DetailFormRequest63";
            case "MT_63_1":
                return "/Permit/DetailTracking63_1";
            case "MT_64":
                return "/Permit/DetailTracking64";
            case "MT_63_2":
                return "/Permit/DetailTracking63_2";
            case "NAMELIST_SURVEY":
            case "NAMELIST_SURVEY_19":
                return "/Permit/DetailTracking63_2_Namelist";
            case "MT_63_2_AGN_CHANGE":
                return "/Permit/DetailTracking63_2_Change";

            // Change
            case "CHANGE_22":
            case "CHANGE_44":
            case "CHANGE_44_22":
            case "CHANGE_45":
            case "CHANGE_44_45":
                return "/Forms/DetailFormRequest44";

            // Renewal
            case "MT_59_RENEWAL":
                return "/Renew59/DetailFormRenew59";
            case "MT_59_MOU_RENEWAL":
                return "/RenewMOU/DetailFormRenewMOU";
            case "MT_62_RENEWAL":
                return "/Renew62/DetailRenew62";
            case "MT_62_BOI_RENEWAL":
                return "/RenewBOI/DetailRenewBOI";
            case "MT_63_RENEWAL":
                return "/Renew63/DetailFormRenew63";
            case "MT_63_1_RENEWAL":
                return "/Renew63_1/DetailFormRenew63_1";
            case "MT_63_2_RENEWAL":
                return "/Renew/DetailFormRenew63_2";
            case "MT_61_EXTEND":
                return "/Renew/DetailFormRenew61";
            case "MT_63_2_AGN_RENEWAL":
                return "/Renew63_2/DetailRequestRenew63_2";

            // Replace card
            case "REPLACE_CARD_25":
            case "REPLACE_CARD_MOU":
                return "/Forms/DetailFormRequest25";
            case "MT_63_2_19":
                return "/Request63_2_19/DetailRequest63_2_19";
            case "MT_63_V_2":
                return "/RequestForm63/DetailFormRequest63_V_2";

            case "MT_63_2_3103_RENEWAL":
            case "MT_63_2_1302_RENEWAL":
                return "/Requtst63_2/DetailRequest63_2_13";
            default:
                return null;
        }
    };

    // const _endpoint = formtypeEndpoint[form_type]
    const _endpoint = GetFormTypeEndpont(form_type)?.trimEnd("/");

    if (!_endpoint) {
        console.error("endpoint not found");
        return;
    }

    const _queryParam = {
        user_id: userid,
        status: status,
        group_id: formid,
        type: institution_id,
        form_type: form_type,
        id: id,
    };

    const _param = Object.entries(_queryParam)
        .filter(
            ([key, value]) =>
                value !== undefined &&
                value !== null &&
                value !== "null" &&
                value !== ""
        )
        .map(([key, value]) => {
            if (app == "Y") {
                return `${key}:${encodeURIComponent(value)}`;
            } else {
                return `${key}=${encodeURIComponent(value)}`;
            }
        });

    if (app == "Y") {
        mobileScriptChannel.postMessage(
            `detailTracking:detail, ${_param.join(", ")}, end_point:${_endpoint}`
        );
    } else {
        //var encrypted_status = CryptoJS.AES.encrypt("" + status + "", "Secret Passphrase");
        //var encrypted_form_type = CryptoJS.AES.encrypt("" + form_type + "", "Secret Passphrase");
        //var encrypted_formid = CryptoJS.AES.encrypt("" + formid + "", "Secret Passphrase");

        if (
            form_type == "MT_13_EXIT" ||
            form_type == "MT_50_1" ||
            form_type == "CHANGE_22" ||
            form_type == "CHANGE_44" ||
            form_type == "CHANGE_44_22" ||
            form_type == "CHANGE_45" ||
            form_type == "CHANGE_44_45" ||
            form_type == "MT_43" ||
            form_type == "REPLACE_CARD_25" ||
            form_type == "REPLACE_CARD_MOU"
        ) {
            const params = Object.fromEntries(
                _param.map((param) => param.split("="))
            );
            const url = `${_endpoint}/${params.group_id}`;
            console.log(`param = ${url}`);
            if (id) {
                location.href = url + '?id=' + id;
            } else {
                location.href = url;
            }
        } else {
            console.log(`param = ${_param.join("&")}`);
            let url = `${_endpoint}?${_param.join("&")}`;

            if (id) {
                // ต่อ &id=... ถ้ามี id
                //    url += `&id=${id}`;
            }

            location.href = url;
        }
    }
}
